from semver import VersionInfo
v = VersionInfo(1, 2, 3)
try:
    print(v < (1, 2, 4))
except TypeError as e:
    print("TypeError:", e)

# Check comparison with string
try:
    print(v < "1.2.3")
except TypeError as e:
    print("String TypeError:", e)

# Check comparison with int
try:
    print(v < 1)
except TypeError as e:
    print("Int TypeError:", e)
